using System.Collections; using UnityEngine; using UnityEngine.UI;
public sealed class CapybaraEyeController : MonoBehaviour { [SerializeField] private Image leftEye, rightEye; [SerializeField] private Vector2 blinkInterval = new(2.5f, 6f); private EyeExpressionDefinition expression; private Coroutine blinking; private void OnEnable() { if (expression != null) StartBlinking(); } private void OnDisable() { if (blinking != null) StopCoroutine(blinking); blinking = null; } public void SetExpression(EyeExpressionDefinition value) { expression = value; Apply(expression != null ? expression.OpenEyes : null); if (isActiveAndEnabled) StartBlinking(); } private void StartBlinking() { if (blinking != null) StopCoroutine(blinking); blinking = expression == null ? null : StartCoroutine(BlinkLoop()); } private IEnumerator BlinkLoop() { while (true) { yield return new WaitForSeconds(Random.Range(blinkInterval.x, blinkInterval.y)); Apply(expression.ClosedEyes); yield return new WaitForSeconds(expression.BlinkDuration); Apply(expression.OpenEyes); } } private void Apply(Sprite sprite) { if (leftEye != null) leftEye.sprite = sprite; if (rightEye != null) rightEye.sprite = sprite; } }
